return {
  [ [[v5748eaic9u95]] ] = { t = [[超小型生物进入占据空间]], q = [=[“超小型及更小的生物”一节说，进入另一个生物的空间会引发[[借机攻击]]，但5尺快步一般不引发借机攻击。如果一个超小型或更小的生物以5尺快步进入另一个生物的空间，它会引发借机攻击吗？]=], a = [=[会。即便是5尺快步，超小型或更小的生物进入另一个生物的空间仍会引发借机攻击（除非它使用了更具体的能力来避免该借机攻击，例如[[猿搏]]专长）。

这并不意味着，一个超小型或更小的生物进入某生物的空间、再以一个移动动作离开受威胁的方格时，会从该生物处引发两次借机攻击；理由与“在同一个移动动作中离开某生物的多个受威胁方格不会引发两次借机攻击”相同。]=], book = [[核心规则书]], date = [[2016/01/01]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9u95]], cat = [[FAQ]], ai = true, pages = { [[不同体型生物的战斗]] } },
  [ [[v5748eaic9sgk]] ] = { t = [[同属性的属性修正叠加]], q = [[来自同一属性的属性修正会叠加吗？例如，能否用两个不同的效果，在同一次骰点上两次加上同一个属性修正？]], a = [=[否。属性加值（例如“力量加值”）就“同一来源的加值不叠加”而言，被视为同一来源。不过，你仍然可以同时加上例如“等同于你魅力修正的偏斜加值”以及你的魅力修正。就此而言，[[圣武士]]的[[圣武士#神恩|神恩]]所给予的无类型的“所有豁免检定上获得等同于其魅力加值（若有）的加值”，被视为与“魅力加值（若有）”是同一个东西；其他任何无类型的“等同于其某属性加值的加值”这类写法也同理。]=], book = [[核心规则书]], date = [[2014/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9sgk]], cat = [[FAQ]], ai = false, pages = { [[魔法]], [[设计法术]] } },
  [ [[v5748eaic9o7j]] ] = { t = [[调制药剂]], q = [[拥有这个专长的角色，能否只通过将DC提高5点，就不经准备而制造出任意他所知法术的药剂？]], a = [[不能。制造药剂时，制造者必须准备并消耗药剂所用的法术，作为制造过程的一部分。这是对“允许施法者通过提高5点DC来略过制造物品的某一项先决条件”这一般性规则的例外。

