  [ [[v5748eaic9rb7]] ] = { t = [[精金武器的硬度]], q = [=[用[[精金]]制成的金属武器，硬度是多少？]=], a = [=[答案取决于这件武器是整件由精金制成，还是一部分是精金、一部分是别的材料。

《核心规则书》第175页的表7–12列出了常见武器的硬度与生命值。该表假定相应武器按实际情况由皮革、木材和／或钢制成。根据表7–13，钢的硬度为10，所以表中整件为钢的武器硬度为10。

带柄武器通常是木柄，而不是金属柄。即便是钢头的[[战斧]]，它的柄也是木头的，所以尽管头部材料的硬度为10，它最薄弱的部分是硬度5的木柄，因此该武器在表7–12上列为硬度5（因为假定你在试图毁坏物体时会瞄准最薄弱的部位）。

对于整件由同一种材料制成的武器（例如单手刀剑），如果该材料不是这种武器的标准材料，就使用表7–13中该材料的硬度，而不用表7–12的默认硬度。例如，木制[[长剑]]硬度为5，玻璃长剑硬度为1，精金长剑硬度为20。

对于并非全部由同一种材料制成的武器（例如木柄金属头的武器），如果其材料不是这种武器的标准材料，就使用表7–13中该武器上最薄弱材料的硬度，而不用表7–12的默认硬度。例如，冰柄（硬度0）钢头（硬度10）的战斧，整体硬度为0，因为它只和它最薄弱的部分一样坚固。同样，冰柄精金头的战斧硬度为0，和它的冰制同类一样。（“使用最薄弱的材料”是个相对的说法：战斧里大概还有少量皮革，但它的主要材料是木头和钢，所以木头是它最薄弱的材料。）

注意，带柄武器的这个“弱点”不影响武器头部的材料属性。木柄精金头的战斧在攻击时仍然算作精金，仍然是精制品，并且攻击检定上仍有+1增强加值，即使它被击破起来和普通的钢战斧一样容易。GM也可以裁定：只波及武器头部的伤害（例如把它浸入一个浅水洼的强酸中）应当使用头部的硬度，而不是木柄的硬度。]=], book = [[核心规则书]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9rb7]], cat = [[FAQ]], ai = false, pages = { [[精金]] } },
  [ [[v5748eaic9v1n]] ] = { t = [[精金与硬度20]], q = [[精金条目说它能绕过小于20的硬度，而硬度条目说精金能绕过20或更低的硬度。我该用哪一条？]], a = [[采用精金条目里的“小于20”。硬度为20的精金，强到足以抵挡精金（这也是为什么精金防具提供的是DR/—，而不是DR/精金）。]], book = [[核心规则书]], date = [[2016/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9v1n]], cat = [[FAQ]], ai = true, pages = { [[精金]], [[硬度]] } },
  [ [[v5748eaic9qdh]] ] = { t = [[魅惑人类与下命令]], q = [[这个法术的“可以试着对受术者下命令”是怎么运作的？]], a = [[法术使目标成为你的朋友。它会友善地对待你（但未必会善待你的盟友），并且只要你们的利益一致，通常就会帮助你。这在很大程度上属于GM的裁量范围。

如果你要求该生物去做它（就你们的友谊而言）通常不会做的事，这时才会用到魅力对抗检定。

例如，如果你用魅惑人类与一名兽人交上了朋友，这名兽人可能会和你分享他的烈酒，并和你聊起即将对附近一处定居点发动的袭击。如果你请他帮忙对付一些骷髅，他很可能会伸出援手。但如果你请他帮你耕地，你就可能需要通过那次检定才能说服他去做。

此解答最初发表于2012年9月11日的Paizo博客。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qdh]], cat = [[FAQ]], ai = true, pages = { [[魅惑人类]] } },
  [ [[v5748eaic9s55]] ] = { t = [[兼职与自发施法]], q = [[我能否用另一个职业的法术位，自发施展我某个职业的法术？]], a = [=[不能。只有当你拥有明确允许这样做的职业特性时才可以，例如[[秘术师#无界施法|无界施法]]。即使两个职业共用同一法术列表，或者其中一个职业允许你把该职业的法术位自发转化为该职业法术列表上的特定法术（例如[[牧师]]和[[德鲁伊]]），这一点也同样适用。]=], book = [[核心规则书]], date = [[2014/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9s55]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9oze]] ] = { t = [[顺势斩与镜影术]], q = [=[我能用顺势斩或[[大顺势斩]]专长，顺势斩向[[镜影术]]制造的幻像，或者从幻像顺势斩向别的目标吗？]=], a = [[不能。如果你的第一次攻击命中了施法者，你就不能像对待真实生物那样顺势斩向某个幻像。如果你的第一次攻击命中的是某个幻像，说明你没能命中你原定的目标（施法者），因此也不能顺势斩。由于你无法专门以某个幻像为目标（因为你分辨不出幻像和真正的施法者），所以你同样无法瞄准一个幻像、再尝试顺势斩向另一个幻像。]], book = [[核心规则书]], date = [[2012/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9oze]], cat = [[FAQ]], ai = false, pages = { [[顺势斩]], [[镜影术]] } },
  [ [[v5748eaic9qd6]] ] = { t = [[顺势斩与5尺快步]], q = [[我能在尝试使用顺势斩专长的中途进行5尺快步，让另一个敌人进入触及范围吗？]], a = [[不能。顺势斩是一个特殊动作，该动作的条件在你开始动作的那一刻检查。那一刻会检查所有可用的目标，确保它们彼此相邻且在你的触及范围内。你不能在动作进行到一半时进行5尺快步，再重新检查条件。如果在攻击开始时你没有两个彼此相邻且都在触及范围内的目标，你甚至不能尝试使用顺势斩进行攻击。

此解答最初发表于2012年9月25日的Paizo博客。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qd6]], cat = [[FAQ]], ai = false, pages = { [[顺势斩]] } },
  [ [[v5748eaic9o78]] ] = { t = [[牧师与神祇偏好武器]], q = [=[神祇的偏好武器是[[重剑]]的牧师，是否能免费获得该剑的军用武器擅长或异种武器擅长？]=], a = [=[由于重剑被列为异种武器，他会获得该武器的[[擅长异种武器]]，使他能够单手使用它。]=], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o78]], cat = [[FAQ]], ai = false, pages = { [[牧师]], [[重剑]] } },
  [ [[v5748eaic9t73]] ] = { t = [[隐蔽与精确伤害]], q = [[隐蔽（指20%那种，不是全隐蔽）会抵消所有种类的精确伤害吗？精确伤害出现在多处规则里，造成了一些混淆。]], a = [=[会。一般来说，隐蔽会抵消所有种类的精确伤害，除非你拥有明确另有说明的特殊能力，例如[[阴影奇袭]]专长，或[[掉链盗贼]]的偷袭。]=], book = [[核心规则书]], date = [[2015/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t73]], cat = [[FAQ]], ai = true, pages = { [[战斗修正]] } },
  [ [[v5748eaic9qig]] ] = { t = [[命令死灵的持续时间]], q = [[不死生物会在我的控制下持续多久？]], a = [=[不死生物会无限期地处于你的控制之下，直到你释放它们（如果是智能不死生物，则直到它在每日一次的豁免检定中成功抵抗你的命令）。

该专长的持续时间并不基于[[操控死灵]]法术1分钟／等级的持续时间（该专长提到那个法术，是为了说明你如何与不死生物交流并向其下达命令，而不是指它的持续时间、材料成分等等）。]=], book = [[核心规则书]], date = [[2013/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qig]], cat = [[FAQ]], ai = false, pages = { [[命令死灵(专长)]] } },
  [ [[v5748eaic9u7j]] ] = { t = [[恶心与动作]], q = [[恶心状态描述里写“这样的角色每回合只能采取一个移动动作”，它真是字面意思，还是只是说我不能采取标准动作？]], a = [=[恶心状态说的就是字面意思。你每轮只能采取一个移动动作，不能采取其他任何动作。对比[[恍惚]]状态，其描述是：“恍惚的生物每轮可以采取一个移动动作或一个标准动作（但不能两者兼有，也不能采取整轮动作）。恍惚的生物仍然可以采取自由动作、迅捷动作和直觉动作。”]=], book = [[核心规则书]], date = [[2016/01/01]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9u7j]], cat = [[FAQ]], ai = true, pages = { [[恶心]] } },
  [ [[v5748eaic9nsy]] ] = { t = [[异界探知与取10]], q = [[这个法术的智力检定能取10吗？]], a = [[被异界存在将你的智力和魅力冲击降至8点，是一个重大且令人分心的威胁，因此你不能在该检定上取10。]], book = [[核心规则书]], date = [[2011/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nsy]], cat = [[FAQ]], ai = true, pages = { [[异界探知]] } },
  [ [[v5748eaic9qjy]] ] = { t = [[反制与解除相反法术]], q = [=[如果我用“截然相反”的法术来反制或解除另一个法术（例如[[祝福术]]对[[绝望术]]、[[加速术]]对[[缓慢术]]等等），我的法术除了解除之外还有别的效果吗？]=], a = [=[这取决于你是把该法术用作反制，还是用作解除。

如果用作反制，你的法术除了反制目标法术之外没有任何效果。如果用作解除，则可能出现来自你的法术或目标法术的“溢出”，具体取决于你影响的目标比对手的法术多还是少。

反制示例：你是一名5级[[法师]]，对手是一名6级[[术士]]。在你的回合，你准备了一个动作来反制法术。术士开始施展缓慢术。你通过[[法术辨识]]检定成功辨识了该法术，并对它施展加速术作为反制。你的加速术反制了缓慢术，两个法术都不产生任何效果。

解除示例：你是一名5级法师，对手是一名6级术士。在她的回合，术士施展缓慢术，以你的6名盟友为目标；这6人全都豁免失败，被减缓。在你的回合，你施展加速术，以你的5名盟友为目标；这会自动解除（无需施法者等级检定）这5名盟友身上的缓慢术，使他们既没有缓慢术的效果也没有加速术的效果（你的第6名盟友仍受缓慢术影响）。注意，这并不只是在加速术持续期间压制缓慢术的效果——这5名盟友身上的缓慢术被彻底解除。另外注意，即使目标对用来解除的法术通常拥有豁免检定或法术抗力可以将其无效或回避（例如施展缓慢术去解除一个已经施展好的加速术），这也无关紧要；为加快游戏进程、避免这类解除出现一边倒的应用，“截然相反”的法术会自动解除其相反的法术，不论受相反法术影响的生物有何意愿。

更新2013年6月5日：澄清了用相反法术进行反制与用它进行解除之间的差异。

更新2013年6月6日：在解除示例中补充了关于豁免检定和法术抗力的文字。]=], book = [[核心规则书]], date = [[2013/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qjy]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9vtl]] ] = { t = [[物品的价格倍数]], q = [[当一件物品有价格倍数时（例如因为体型、异形或材质），这个倍数是在加上精制或特殊材料之类的额外费用之前应用，还是之后应用？]], a = [=[先把基础物品的总价加起来，包括任何特殊材料。然后乘以表6-8中针对体型和异形的倍数。之后，加上精制的额外费用（如果它还不是特殊材料的一部分）。最后，应用折扣之类的倍数，例如制造物品时的1/3费用倍数。例如，[[链甲衫]]价格为100 gp，而[[秘银]]链甲衫在加上秘银的+1,000 gp费用后为1,100 gp。如果你要应用以[[工艺]]技能制造物品的1/3费用倍数、表6-8中基于体型和身体类型的价格倍数，或两者兼有，你都应把这些倍数应用到秘银链甲衫完整的1,100 gp价格上。这意味着，为符文巨人打造的秘银链甲衫价格为8,800 gp，为泰拉斯奎兽打造的秘银链甲衫价格为35,200 gp。另一方面，一把大型的精制[[寒铁]][[巨剑]]价格为500 gp（巨剑50 gp，因寒铁翻倍，因大型武器再翻倍，最后才加上精制，因为寒铁并不总是精制品）。]=], book = [[核心规则书]], date = [[2017/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vtl]], cat = [[FAQ]], ai = true, pages = { [[装备]], [[工艺]] } },
  [ [[v5748eaic9o61]] ] = { t = [[额外伤害骰与重击]], q = [=[来自[[导能打击]]，或[[元素之触]]、[[火焰箭]]等法术的额外伤害骰，会在[[重击]]时翻倍吗？]=], a = [=[不会。《[[核心规则书]]》第179页“倍数伤害”一节写道：“例外：武器正常伤害之外的额外伤害骰永远不会翻倍。”

一般规则是：重击时唯一会翻倍的骰子，是基础武器本身的骰子（[[长剑]]的d8、[[巨剑]]的2d6，等等）。]=], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o61]], cat = [[FAQ]], ai = false, pages = { [[战斗中的数据计算]] } },
  [ [[v5748eaic9qe9]] ] = { t = [[伤害减免与法术伤害]], q = [[伤害减免（DR）如何与造成钝击、穿刺或挥砍伤害的魔法效果相互作用？]], a = [=[《[[怪物图鉴]]》对伤害减免的定义（第299页）写道“该生物受到来自能量攻击（即使是非魔法的）、法术、类法术能力和超自然能力的伤害时，承受正常伤害”，但这其实只是指那些没有明确指定为某种特定类型（例如火焰伤害或穿刺伤害）的伤害。换言之，伤害减免无法防御来自魔法攻击的“无类型伤害”。

不过，如果某个魔法攻击明确说明它造成钝击、穿刺或挥砍伤害，伤害减免就会像对待物理武器造成的伤害那样，正常地作用于这些伤害。（否则这种魔法攻击不如干脆没有伤害类型，因为它只会在极少数边角情况下与钝击／穿刺／挥砍伤害产生关联，例如泥形生物是否会因该攻击而分裂。）

例如，[[冰风暴]]法术造成3d6点钝击伤害和2d6点寒冷伤害。如果你对一群[[丧尸]]施展冰风暴，丧尸的DR 5/挥砍会为它们抵挡该法术的5点钝击伤害。它们的DR对该法术的寒冷伤害没有帮助，因为DR不适用于能量攻击。]=], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qe9]], cat = [[FAQ]], ai = false, pages = { [[伤害减免]] } },
}